#nullable enable // autogenerated

using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.giantStone)]
    public class GiantStone : EntityBehaviourDefinition
    {
        public GiantStone(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostContactGround(Entity entity, Vector3 velocity)
        {
            base.PostContactGround(entity, velocity);
            if (entity.IsAboveLand())
            {
                entity.PlaySound(VanillaSoundID.giantStoneLand);
                entity.Level.ShakeScreen(3, 0, 5);
            }
        }
    }
}
